Rules.InvariantScript:
Set(workerVar,{copyName:ThisItem.Name,base64Image:ThisItem.Value});
If(workerVar in RTEImages,Remove(RTEImages,LookUp(RTEImages, ThisItem.Value = base64Image)));
Remove(attItems,LookUp(attItems,ThisItem.Value = Value));
Remove(JointAttachments,ThisItem)

ForAll
(
    Self.Attachments As Attachment,
    If(Not(Attachment in JointAttachments),Collect(JointAttachments,{Name:Attachment.Name,Value:Attachment.Value}))
);
ClearCollect(attItems,Self.Attachments);
Reset(AddMediaAttachmentControl_1);

If(Len(TextInput16.Text)>0,
//Create a new record, assign info to a temp variable
Set(tempRec,Patch('Feedback/Bugs',Defaults('Feedback/Bugs'),
{
    Screen:App.ActiveScreen.Name,
    FeedbackType: If(Checkbox6.Value,{Value:"Bug"},{Value:"Feedback"}),
    Comments:TextInput16.Text&If(TicketCategoryID = 1 And TicketSubCategoryID =9 And TicketSpecificIssue =1, Blank(),Char(10)&Char(10)&"Ticket Selection"&Char(10)&LookUp(Category,ID = TicketCategoryID).Name&">"&LookUp(Category,ID = TicketSubCategoryID).Name&">"&LookUp(Category,ID = TicketSpecificIssue).Name),
    FeedbackChecked:false
}));
//Process media
ForAll(
    attItems As Attachment,
            FeedbackAttachFiles.Run(
            tempRec.ID,
            {
                file:{
                    contentBytes: Attachment.Value,
                    name: Attachment.Name
                }
            }
        ) 
);
ForAll(
    FeedbackImages As FBI,
    With({varHTMLTable: Split(FBI.base64Image , "<img")}, If(CountRows(varHTMLTable)>1, With({varB64Start:Find("<img",FBI.base64Image)+32},With({varB64End:Find("""",Mid(FBI.base64Image,varB64Start))-1},CopyPasteFeedback.Run(Mid(FBI.base64Image,varB64Start,varB64End),FBI.copyName&".png",tempRec.ID)
))))
        );
Clear(FeedbackImages);
Clear(JointAttachments);
Clear(attItems);
Reset(TextInput16);
Reset(Checkbox6);
FeedbackBugReport.CloseReport()

,Notify("Feedback cannot be blank",NotificationType.Error));
